/** Owner records plus a separate private concern section, with no public listing/admin controls. */
public final class PetActivity extends AppCompatActivity {
    private PetViewModel model;
    private LinearLayout content,results,rootContent,petSection,concernSection;
    private TextView status,detailStatus;
    private final Map<String,TextInputEditText> fields=new LinkedHashMap<>();
    private final Map<String,TextInputLayout> layouts=new HashMap<>();
    private final Map<String,MaterialButton> buttons=new HashMap<>();
    private Spinner sex,basis;
    private MaterialCheckBox marksUnknown,care;
    private boolean rendering;
    private long rendered=-1,shownConflict=-1;
    private androidx.appcompat.app.AlertDialog dialog;
    @Override protected void onCreate(Bundle saved){super.onCreate(saved);EdgeToEdge.enable(this);setContentView(R.layout.activity_pet);
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.pet_root),(v,insets)->{Insets bars=insets.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout()),ime=insets.getInsets(WindowInsetsCompat.Type.ime());v.setPadding(bars.left,bars.top,bars.right,Math.max(bars.bottom,ime.bottom));return insets;});
        content=findViewById(R.id.pet_content);model=new ViewModelProvider(this).get(PetViewModel.class);
        rootContent=content;
        heading(R.string.pet_title);label(R.string.pet_disclosure);status=label(0);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);
        action("retry",R.string.pet_retry,()->{if(model.pending!=null)model.execute(model.pending);},false);action("reconcile",R.string.pet_reconcile,model::reconcile,false);action("resolve",R.string.pet_resolve,this::showConflict,false);
        action("release",R.string.pet_release_restore,()->confirm(R.string.pet_restore,model::releaseRestored),false);
        action("openConcern",R.string.pet_challenge_title,()->{model.challengeMode=true;render();},false);
        action("refresh",R.string.pet_refresh,()->discard(()->model.list("pets",false)),false);action("new",R.string.pet_new,()->discard(model::newPet),false);action("next",R.string.pet_next,()->discard(()->model.list(model.pageKind,true)),false);
        results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);content.addView(results);detailStatus=label(0);
        petSection=new LinearLayout(this);petSection.setOrientation(LinearLayout.VERTICAL);rootContent.addView(petSection);content=petSection;
        field("displayName",R.string.pet_name,false);field("species",R.string.pet_species,false);field("breed",R.string.pet_breed,false);sex=selection(R.string.pet_sex,R.array.pet_sexes);
        field("ageMonths",R.string.pet_age,false).setInputType(android.text.InputType.TYPE_CLASS_NUMBER);field("ageObservedAt",R.string.pet_observed,false);field("marks",R.string.pet_marks,true);marksUnknown=check(R.string.pet_marks_unknown);label(R.string.pet_illustration);
        basis=selection(R.string.pet_basis,R.array.pet_bases);care=check(R.string.pet_care);field("explanation",R.string.pet_explanation,true);label(R.string.pet_claim_help);
        action("register",R.string.pet_register,()->confirm(R.string.pet_disclosure,()->command("register_pet")),true);action("identity",R.string.pet_revise,()->command("revise_identity"),true);action("claim",R.string.pet_claim_save,()->command("revise_claim"),false);action("submit",R.string.pet_claim_submit,()->confirm(R.string.pet_claim_help,()->command("submit_claim")),false);action("withdraw",R.string.pet_withdraw,()->confirm(R.string.pet_discard_help,()->command("withdraw_claim")),false);action("suspend",R.string.pet_suspend,()->confirm(R.string.pet_discard_help,()->command("suspend_offering")),false);
        field("chip",R.string.pet_chip,false);field("notes",R.string.pet_chip_notes,true);label(R.string.pet_chip_help);action("chip",R.string.pet_chip_save,()->command("save_chip"),false);action("history",R.string.pet_history,()->discard(()->model.list("receipts",false)),false);
        concernSection=new LinearLayout(this);concernSection.setOrientation(LinearLayout.VERTICAL);rootContent.addView(concernSection);content=concernSection;
        heading(R.string.pet_challenge_title);label(R.string.pet_challenge_help);field("target",R.string.pet_target,false);action("suspendKnown",R.string.pet_suspend_known,()->confirm(R.string.pet_discard_help,()->{if(!PetSchema.id(text("target"))){fail("target",R.string.pet_invalid);return;}model.suspendKnown(text("target"));}),false);field("statement",R.string.pet_statement,true);action("challenge",R.string.pet_challenge_submit,()->confirm(R.string.pet_challenge_help,()->command("submit_challenge")),true);action("challenges",R.string.pet_challenges,()->discard(()->model.list("challenges",false)),false);
        content=rootContent;action("back",R.string.auth_back,this::leave,false);
        disableState(findViewById(R.id.pet_root));getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){public void handleOnBackPressed(){leave();}});
        model.changes.observe(this,x->render());((AniloveApplication)getApplication()).auth().state().observe(this,s->{if(s.uid==null)clearAndFinish();else render();});
    }
    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
    private void disableState(View v){v.setSaveEnabled(false);v.setSaveFromParentEnabled(false);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)disableState(g.getChildAt(i));}}
    private TextView label(int id){TextView t=new TextView(this);t.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodyMedium);if(id!=0)t.setText(id);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(12);t.setLayoutParams(p);t.setSaveEnabled(false);content.addView(t);return t;}
    private void heading(int id){TextView t=label(id);t.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_TitleLarge);ViewCompat.setAccessibilityHeading(t,true);((LinearLayout.LayoutParams)t.getLayoutParams()).topMargin=dp(28);}
    private TextInputEditText field(String key,int hint,boolean multiline){TextInputLayout l=(TextInputLayout)getLayoutInflater().inflate(R.layout.pet_field,content,false);l.setHint(getString(hint));TextInputEditText e=(TextInputEditText)l.getEditText();e.setId(View.generateViewId());if(multiline){e.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);e.setMinLines(3);e.setGravity(Gravity.TOP);}fields.put(key,e);layouts.put(key,l);content.addView(l);e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){if(!rendering)model.text.put(key,s.toString());}public void afterTextChanged(Editable e){}});return e;}
    private Spinner selection(int title,int array){TextView label=label(title);Spinner s=new Spinner(this);s.setId(View.generateViewId());s.setMinimumHeight(dp(48));s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,getResources().getStringArray(array)));label.setLabelFor(s.getId());content.addView(s,new LinearLayout.LayoutParams(-1,-2));s.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int position,long id){capture();}public void onNothingSelected(AdapterView<?> p){}});return s;}
    private MaterialCheckBox check(int id){MaterialCheckBox c=new MaterialCheckBox(this);c.setText(id);c.setMinHeight(dp(48));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);content.addView(c,p);c.setOnCheckedChangeListener((v,on)->capture());return c;}
    private MaterialButton action(String key,int id,Runnable task,boolean primary){MaterialButton b=(MaterialButton)getLayoutInflater().inflate(R.layout.pet_button,content,false);b.setText(id);if(!primary){b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(MaterialColors.getColor(b,com.google.android.material.R.attr.colorSecondaryContainer)));b.setTextColor(MaterialColors.getColor(b,com.google.android.material.R.attr.colorOnSecondaryContainer));}b.setOnClickListener(v->task.run());content.addView(b);buttons.put(key,b);return b;}
    private String text(String key){return model.text.getOrDefault(key,"").trim();}
    private void capture(){if(rendering||model==null||sex==null||basis==null||marksUnknown==null||care==null)return;model.sex=Math.max(0,sex.getSelectedItemPosition());model.basis=Math.max(0,basis.getSelectedItemPosition());model.marksUnknown=marksUnknown.isChecked();model.care=care.isChecked();}
    private Map<String,Object> identity(){Long months=null;Timestamp observed=null;if(!text("ageMonths").isEmpty()){months=Long.parseLong(text("ageMonths"));LocalDate d=LocalDate.parse(text("ageObservedAt"));if(d.isAfter(LocalDate.now(ZoneOffset.UTC)))throw new IllegalArgumentException();observed=new Timestamp(java.util.Date.from(d.atStartOfDay(ZoneOffset.UTC).toInstant()));}else if(!text("ageObservedAt").isEmpty())throw new IllegalArgumentException();return PetSchema.map("displayName",text("displayName"),"species",text("species"),"breed",text("breed"),"sex",PetSchema.SEXES.get(model.sex),"ageMonths",months,"ageObservedAt",observed,"marks",model.marksUnknown?"":text("marks"),"marksUnknown",model.marksUnknown,"illustrationKey",model.detail==null?"default":PetSchema.nested(model.detail.revision,"identity").get("illustrationKey"));}
    private Map<String,Object> declaration(){return PetSchema.map("basis",PetSchema.BASES.get(model.basis),"reportedCare",model.care,"explanation",text("explanation"));}
    private void fail(String key,int message){layouts.get(key).setError(getString(message));fields.get(key).requestFocus();}
    private void command(String type){capture();for(TextInputLayout l:layouts.values())l.setError(null);Map<String,Object> input;String target=model.petId;long identity=model.identityVersion(),claim=model.claimVersion(),authority=model.authorityVersion(),priv=model.privateVersion();
        try{if("submit_challenge".equals(type)){target=text("target");identity=0;claim=0;authority=0;if(!PetSchema.id(target)){fail("target",R.string.pet_invalid);return;}if(!PetSchema.text(text("statement"),1,1000,3000)){fail("statement",R.string.pet_invalid);return;}input=PetSchema.map("statement",text("statement"));}
            else if("save_chip".equals(type)){if(!text("chip").isEmpty()&&!PetSchema.text(text("chip"),1,64,256)){fail("chip",R.string.pet_invalid);return;}if(!PetSchema.text(text("notes"),0,500,2000)){fail("notes",R.string.pet_invalid);return;}input=PetSchema.map("chip",text("chip").isEmpty()?null:text("chip"),"notes",text("notes"));}
            else if("suspend_offering".equals(type)){identity=PetSchema.version(model.detail.authority,"identityVersion");claim=PetSchema.version(model.detail.authority,"claimVersion");input=Collections.emptyMap();}
            else{Map<String,Object> i=Arrays.asList("register_pet","revise_identity","submit_claim").contains(type)?identity():Collections.emptyMap(),c="withdraw_claim".equals(type)?PetSchema.declarationOf(model.detail.claim):declaration();if("register_pet".equals(type)||"revise_identity".equals(type)){for(String key:new String[]{"displayName","species","breed","marks"}){int max="marks".equals(key)?500:"species".equals(key)?40:80;int min="species".equals(key)||"marks".equals(key)&&!model.marksUnknown?1:0;if(!PetSchema.text(i.get(key),min,max,max*4)){fail(key,R.string.pet_invalid);return;}}if(!PetSchema.identity(i)){fail("ageMonths",R.string.pet_invalid_age);return;}}
                if(!"revise_identity".equals(type)&&!PetSchema.declaration(c)){fail("explanation",R.string.pet_invalid);return;}if("submit_claim".equals(type)&&(!c.equals(PetSchema.declarationOf(model.detail.claim))||!i.equals(PetSchema.nested(model.detail.revision,"identity")))){status.setText(R.string.pet_saved_claim);return;}input="register_pet".equals(type)?PetSchema.map("identity",i,"claim",c):"revise_identity".equals(type)?PetSchema.map("identity",i):PetSchema.map("claim",c);}
        }catch(RuntimeException invalid){fail("ageObservedAt",R.string.pet_invalid_age);return;}
        if(target!=null)model.execute(new PetCommand(type,target,UUID.randomUUID().toString(),identity,claim,authority,priv,input));
    }
    private boolean dirty(){if(model.pending!=null||model.busy||model.restored)return true;if(!text("statement").isEmpty())return true;try{if(model.detail!=null)return !identity().equals(PetSchema.nested(model.detail.revision,"identity"))||!declaration().equals(PetSchema.declarationOf(model.detail.claim))||!Objects.equals(text("chip").isEmpty()?null:text("chip"),model.detail.chip==null?null:model.detail.chip.get("chip"))||!text("notes").equals(model.detail.chip==null?"":model.detail.chip.get("notes"));}catch(RuntimeException ignored){return true;}return model.text.values().stream().anyMatch(s->!s.trim().isEmpty());}
    private void discard(Runnable action){capture();if(!dirty()){action.run();return;}dialog=new MaterialAlertDialogBuilder(this).setTitle(R.string.pet_discard).setMessage(R.string.pet_discard_help).setPositiveButton(R.string.profile_discard,(d,w)->action.run()).setNegativeButton(R.string.profile_keep,null).show();}
    private void leave(){if(model.challengeMode){model.challengeMode=false;render();return;}discard(this::finish);}
    private void confirm(int message,Runnable action){dialog=new MaterialAlertDialogBuilder(this).setMessage(message).setPositiveButton(android.R.string.ok,(d,w)->action.run()).setNegativeButton(android.R.string.cancel,null).show();}
    private boolean ready(){AuthState s=((AniloveApplication)getApplication()).auth().state().getValue();return s!=null&&!s.pending&&s.setupReady&&s.verified&&s.verificationKnown&&s.authority==AuthState.Authority.ACTIVE;}
    private void clearAndFinish(){findViewById(R.id.pet_root).setVisibility(View.INVISIBLE);rendering=true;for(TextInputEditText f:fields.values())f.setText("");results.removeAllViews();detailStatus.setText("");if(dialog!=null)dialog.dismiss();finish();}
    private String state(String s){switch(s){case "draft":return getString(R.string.pet_state_draft);case "submitted":return getString(R.string.pet_state_submitted);case "needs_information":return getString(R.string.pet_state_needs_information);case "accepted_for_demo":return getString(R.string.pet_state_accepted_for_demo);case "rejected":return getString(R.string.pet_state_rejected);default:return getString(R.string.pet_state_withdrawn);}}
    private String permission(PetOfferAuthority.Reason r){int id;switch(r){case ALLOWED_FOR_DEMO:id=R.string.pet_permission_ready;break;case NOT_READY:id=R.string.pet_reason_not_ready;break;case UNKNOWN_GATE:id=R.string.pet_reason_unknown;break;case NOT_EDITOR:id=R.string.pet_reason_actor;break;case ARCHIVED:id=R.string.pet_reason_archive;break;case STALE_REVIEW:id=R.string.pet_reason_stale;break;case HELD:id=R.string.pet_reason_hold;break;case BLOCKED:id=R.string.pet_reason_blocked;break;default:id=R.string.pet_reason_activity;}return getString(id);}
    private void render(){if(model.lost){clearAndFinish();return;}if(rendered!=model.formRevision){rendering=true;for(Map.Entry<String,TextInputEditText> e:fields.entrySet())e.getValue().setText(model.text.getOrDefault(e.getKey(),""));sex.setSelection(model.sex);basis.setSelection(model.basis);marksUnknown.setChecked(model.marksUnknown);care.setChecked(model.care);rendering=false;rendered=model.formRevision;}
        petSection.setVisibility(model.challengeMode?View.GONE:View.VISIBLE);concernSection.setVisibility(model.challengeMode?View.VISIBLE:View.GONE);buttons.get("openConcern").setVisibility(model.challengeMode?View.GONE:View.VISIBLE);buttons.get("release").setVisibility(model.restored?View.VISIBLE:View.GONE);
        AuthState auth=((AniloveApplication)getApplication()).auth().state().getValue();boolean enabled=!model.busy&&model.pending==null&&!model.restored&&model.conflict==null&&auth!=null&&!auth.pending;boolean exists=model.detail!=null;for(MaterialButton b:buttons.values())b.setEnabled(enabled);buttons.get("back").setEnabled(true);buttons.get("retry").setVisibility(model.pending!=null?View.VISIBLE:View.GONE);buttons.get("retry").setEnabled(model.pending!=null&&!model.busy);buttons.get("reconcile").setVisibility(model.restored?View.VISIBLE:View.GONE);buttons.get("reconcile").setEnabled(model.restored&&!model.busy);buttons.get("resolve").setVisibility(model.conflict!=null?View.VISIBLE:View.GONE);buttons.get("resolve").setEnabled(model.conflict!=null&&!model.busy);for(String k:new String[]{"refresh","history","challenges"})buttons.get(k).setEnabled(!model.busy&&model.pending==null);
        for(Map.Entry<String,TextInputEditText> e:fields.entrySet())e.getValue().setEnabled(enabled&&("target".equals(e.getKey())||"statement".equals(e.getKey())||exists||model.editingNew));sex.setEnabled(enabled&&(exists||model.editingNew));basis.setEnabled(enabled&&(exists||model.editingNew));marksUnknown.setEnabled(enabled&&(exists||model.editingNew));care.setEnabled(enabled&&(exists||model.editingNew));for(String key:new String[]{"identity","claim","submit","chip"})buttons.get(key).setEnabled(enabled&&exists&&ready());buttons.get("register").setEnabled(enabled&&model.editingNew&&ready());buttons.get("withdraw").setEnabled(enabled&&exists);buttons.get("suspend").setEnabled(enabled&&exists&&"enabled".equals(model.detail.authority.get("status"))&&Objects.equals(model.detail.pet.get("editorUid"),model.detail.authority.get("offerUid")));buttons.get("next").setVisibility(model.page!=null&&model.page.cursor!=null?View.VISIBLE:View.GONE);
        fields.get("chip").setEnabled(enabled&&exists&&ready());fields.get("notes").setEnabled(enabled&&exists&&ready());buttons.get("new").setEnabled(enabled&&model.page!=null&&"pets".equals(model.pageKind)&&!model.challengeMode);buttons.get("release").setEnabled(model.restored&&!model.busy&&model.page!=null&&"pets".equals(model.pageKind));
        int msg=model.restored?R.string.pet_restore:model.busy?R.string.pet_busy:model.committed?R.string.pet_committed:!ready()?R.string.pet_denied:R.string.pet_disclosure;switch(model.code){case CONFLICT:msg=R.string.pet_conflict;break;case DENIED:msg=R.string.pet_denied;break;case UNKNOWN_SCHEMA:msg=R.string.pet_schema;break;case UNAVAILABLE:msg=R.string.pet_network;break;case UNKNOWN_OUTCOME:msg=R.string.pet_unknown;break;case NOT_FOUND:msg=R.string.pet_restore;break;default:break;}status.setText(msg);
        if(exists){PetIdentityRepository.Detail d=model.detail;PetOfferAuthority.Reason reason=PetOfferAuthority.evaluate(model.petId,auth==null?null:auth.uid,model.identityVersion(),ready(),d.pet,d.claim,d.authority,d.gate,d.slot);detailStatus.setText(getString(R.string.pet_detail,model.petId,model.identityVersion(),model.claimVersion(),state((String)d.claim.get("reviewState")),permission(reason)));}else detailStatus.setText("");
        results.removeAllViews();if(model.page!=null){if(model.page.rows.isEmpty()){TextView t=new TextView(this);t.setText(R.string.pet_empty);results.addView(t);}for(Map<String,Object> row:model.page.rows){if("pets".equals(model.pageKind)){MaterialButton b=(MaterialButton)getLayoutInflater().inflate(R.layout.pet_button,results,false);b.setText((String)row.get("petId"));b.setEnabled(enabled);b.setOnClickListener(v->discard(()->{model.challengeMode=false;model.select((String)row.get("petId"));}));results.addView(b);}else{TextView t=new TextView(this);t.setTextAppearance(com.google.android.material.R.style.TextAppearance_Material3_BodyMedium);t.setPadding(0,dp(12),0,dp(12));t.setText("receipts".equals(model.pageKind)?getString(R.string.pet_receipt,row.get("petId"),commandLabel((String)row.get("type")),date((Timestamp)row.get("recordedAt"))):getString(R.string.pet_challenge_row,row.get("targetPetId"),getString("received".equals(row.get("status"))?R.string.pet_received:"triaged".equals(row.get("status"))?R.string.pet_triaged:R.string.pet_closed),"".equals(row.get("response"))?getString(R.string.pet_pending):row.get("response")));if("receipts".equals(model.pageKind)){Map<String,Object> input=PetSchema.nested(row,"input");if(input.containsKey("reason"))t.append("\n"+(String)input.get("reason"));}t.setSaveEnabled(false);results.addView(t);}}}
        if(model.conflict!=null&&shownConflict!=model.conflictRevision){shownConflict=model.conflictRevision;showConflict();}
    }
    private String date(Timestamp t){return java.text.DateFormat.getDateTimeInstance().format(t.toDate())+" ("+t.toDate().toInstant()+")";}
    private String commandLabel(String type){int s;switch(type){case "register_pet":s=R.string.pet_record_register;break;case "revise_identity":s=R.string.pet_record_identity;break;case "submit_claim":s=R.string.pet_record_submit;break;case "revise_claim":s=R.string.pet_record_claim;break;case "withdraw_claim":s=R.string.pet_record_withdraw;break;case "suspend_offering":s=R.string.pet_record_suspend;break;case "submit_challenge":s=R.string.pet_record_concern;break;default:s=R.string.pet_record_review;}return getString(s);}
    private String snapshot(PetIdentityRepository.Detail d){if(d==null)return getString(R.string.profile_none);Map<String,Object> i=PetSchema.nested(d.revision,"identity");String age=i.get("ageMonths")==null?getString(R.string.profile_none):getString(R.string.pet_estimated_age,(Long)i.get("ageMonths"),((Timestamp)i.get("ageObservedAt")).toDate().toInstant().atZone(ZoneOffset.UTC).toLocalDate());return getString(R.string.pet_snapshot,i.get("displayName"),i.get("species"),i.get("breed"),age,Boolean.TRUE.equals(i.get("marksUnknown"))?getString(R.string.pet_marks_unknown):i.get("marks"),d.claim.get("explanation"),d.chip==null||d.chip.get("chip")==null?getString(R.string.profile_none):d.chip.get("chip"),d.chip==null?"":d.chip.get("notes"),PetSchema.version(d.pet,"identityVersion"),PetSchema.version(d.claim,"claimVersion"),PetSchema.version(d.authority,"authorityVersion"));}
    private void showConflict(){if(model.conflict==null)return;StringBuilder intended=new StringBuilder(model.conflictCommand==null?"":commandLabel(model.conflictCommand.type));for(Map.Entry<String,TextInputLayout> e:layouts.entrySet())if(!Arrays.asList("target","statement").contains(e.getKey()))intended.append('\n').append(e.getValue().getHint()).append(": ").append(text(e.getKey()));intended.append('\n').append(getString(R.string.pet_sex)).append(": ").append(getResources().getStringArray(R.array.pet_sexes)[model.sex]).append('\n').append(getString(R.string.pet_basis)).append(": ").append(getResources().getStringArray(R.array.pet_bases)[model.basis]).append('\n').append(getString(R.string.pet_care)).append(": ").append(getString(model.care?android.R.string.yes:android.R.string.no));dialog=new MaterialAlertDialogBuilder(this).setTitle(R.string.pet_conflict).setMessage(getString(R.string.pet_diff,snapshot(model.detail),snapshot(model.conflict),intended.toString())).setPositiveButton(R.string.profile_keep,(d,w)->model.resolve(true)).setNegativeButton(R.string.profile_discard,(d,w)->model.resolve(false)).show();}
    @Override protected void onDestroy(){if(dialog!=null)dialog.dismiss();super.onDestroy();}
}
